edits.oldText:
export function statusLabel(status: "open" | "closed") {
  if (status === "open") return "Open";
  if (status === "closed") return "Closed";
  return "Closed";
}

edits.newText:
export function statusLabel(status: "open" | "closed") {
  const labels = { open: "Open", closed: "Closed" } as const;
  return labels[status];
}
